function lookupAsset(key: string): BrandingAsset | undefined {
  // hasOwn guard: request-path keys like '__proto__'/'constructor' must not
  // resolve through the prototype chain (they used to return 500s from atob).
  return Object.hasOwn(BRANDING_ASSETS, key) ? BRANDING_ASSETS[key] : undefined;
}

export function getBrandingAsset(requestPath: string): { data: Uint8Array | string; mime: string } | null {
  const cleanPath = requestPath.replace(/^\/+/, '').replace(/\\+/g, '/');
  
  // Direct file matches
  let asset = lookupAsset(cleanPath) ||
    lookupAsset('branding/' + cleanPath) ||
    lookupAsset('branding/dist/symbol/' + cleanPath) ||
    lookupAsset('branding/dist/horizontal/' + cleanPath);
  
  // Specific alias routes
  if (!asset) {
    if (cleanPath === 'favicon.ico') asset = BRANDING_ASSETS['branding/dist/symbol/favicon.ico'];
    else if (cleanPath === 'favicon.svg') asset = BRANDING_ASSETS['branding/dist/symbol/favicon.svg'];
    else if (cleanPath === 'favicon-16.png') asset = BRANDING_ASSETS['branding/dist/symbol/favicon-16.png'];
    else if (cleanPath === 'favicon-32.png') asset = BRANDING_ASSETS['branding/dist/symbol/favicon-32.png'];
    else if (cleanPath === 'favicon-48.png') asset = BRANDING_ASSETS['branding/dist/symbol/favicon-48.png'];
    else if (cleanPath === 'apple-touch-icon.png') asset = BRANDING_ASSETS['branding/dist/symbol/apple-touch-icon.png'];
    else if (cleanPath === 'icon-192.png') asset = BRANDING_ASSETS['branding/dist/symbol/icon-192.png'];
    else if (cleanPath === 'icon-512.png' || cleanPath === 'logo.png') asset = BRANDING_ASSETS['branding/dist/symbol/icon-512.png'];
    else if (cleanPath === 'maskable-512.png') asset = BRANDING_ASSETS['branding/dist/symbol/maskable-512.png'];
    else if (cleanPath === 'site.webmanifest') asset = BRANDING_ASSETS['branding/dist/symbol/site.webmanifest'];
    else if (cleanPath === 'logo.svg') asset = BRANDING_ASSETS['branding/dist/symbol/nuvio-symbol-app-icon.svg'];
  }

  if (!asset) return null;

  if (asset.isText) {
    return { data: asset.data, mime: asset.mime };
  }

  // Convert base64 to Uint8Array for binary assets
  const binaryString = atob(asset.data);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return { data: bytes, mime: asset.mime };
}
